// LeadFlow Free - step 1: paste a real (messy) lead export here.
// The header row is required; columns are mapped by name, so the order does not matter.
// Sample rows are synthetic. Replace them with your own export, or put
// "Read/Write Files from Disk" + "Extract from File" (CSV) in front of this node
// and use the CSV text as the csv field.
const csv = [
  'First Name,Last-Name ,E-MAIL ,Company Name,Phone',
  '  Ana ,Kovač,ANA.KOVAC@PrimaStudio.rs ,Prima Studio,+381 11 123 4567',
  'Marko,Petrović,marko.petrovic@ petroco.rs,Petro Co d.o.o.,',
  'Sara,Alić,sara@alfa.rs,Alfa,"+381 60 111 2222"',
  ',Nikolić,,Beta DOO,060 333 4444',
  'Jürgen,Müller,j.mueller@muller-gmbh.de,Müller GmbH,+49 30 555',
].join('\n');

return [{ json: { csv } }];

// LeadFlow Free - step 2: normalise headers, trim values, validate addresses.
// Header text varies between exports ("E-MAIL", "Last-Name ", "Company Name"), so the
// header row is mapped onto standard field names instead of being trusted as-is.
function splitCsvLine(line) {
  const cells = [];
  let cur = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"') {
        if (line[i + 1] === '"') { cur += '"'; i++; } else { quoted = false; }
      } else { cur += ch; }
    } else if (ch === '"') {
      quoted = true;
    } else if (ch === ',' || ch === ';' || ch === '\t') {
      cells.push(cur); cur = '';
    } else {
      cur += ch;
    }
  }
  cells.push(cur);
  return cells;
}

function standardField(header) {
  const h = String(header).trim().toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (/^(first|first ?name|fname|given name)$/.test(h)) return 'first_name';
  if (/^(last|last ?name|surname|lname|family name)$/.test(h)) return 'last_name';
  if (/(e ?mail|mail)/.test(h) && !/phone/.test(h)) return 'email';
  if (/(company|organi[sz]ation|business|firm)/.test(h)) return 'company';
  if (/(domain|website|site|url)/.test(h)) return 'domain';
  if (/(phone|mobile|tel)/.test(h)) return 'phone';
  return h.replace(/ /g, '_') || 'column';
}

const EMAIL = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;
const csv = String($json.csv || '').replace(/^\uFEFF/, '');
const lines = csv.split(/\r?\n/).filter((line) => line.trim() !== '');

if (lines.length < 2) {
  return [{ json: { headers: [], rows_in: 0, cleaned: [], rejected: [] } }];
}

const headers = splitCsvLine(lines[0]).map(standardField);
const cleaned = [];
const rejected = [];

for (const line of lines.slice(1)) {
  const cells = splitCsvLine(line);
  const row = {};
  headers.forEach((field, index) => {
    row[field] = String(cells[index] === undefined ? '' : cells[index]).trim();
  });

  row.first_name = row.first_name || '';
  row.last_name = row.last_name || '';
  row.company = row.company || '';
  row.email = (row.email || '').toLowerCase().replace(/\s+/g, '');
  row.domain = (row.domain || '')
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/.*$/, '');

  if (!row.email) {
    rejected.push({ ...row, reason: 'missing email' });
    continue;
  }
  if (!EMAIL.test(row.email)) {
    rejected.push({ ...row, reason: 'invalid email: ' + row.email });
    continue;
  }
  if (!row.domain) row.domain = row.email.split('@')[1];
  row.full_name = (row.first_name + ' ' + row.last_name).trim();
  cleaned.push(row);
}

return [{ json: { headers, rows_in: lines.length - 1, cleaned, rejected } }];

// LeadFlow Free - step 3: one readable report instead of a wall of items.
const input = $input.first().json;
const cleaned = input.cleaned || [];
const rejected = input.rejected || [];
const rowsIn = input.rows_in || 0;
const plural = (n, one, many) => n + ' ' + (n === 1 ? one : many);

return [{
  json: {
    rows_in: rowsIn,
    valid_rows: cleaned.length,
    rejected_rows: rejected.length,
    note: plural(cleaned.length, 'row is', 'rows are') + ' importable out of ' + rowsIn +
      '; ' + plural(rejected.length, 'row could', 'rows could') + ' not be fixed' +
      (rejected.length ? ' and ' + (rejected.length === 1 ? 'is' : 'are') + ' listed in rejected with a reason.' : '.'),
    cleaned_leads: cleaned,
    rejected,
  },
}];
